    final pinned = _pinnedPackFor(rest, resolver);
    final packRoot = pinned?.packRoot;
    try {
      final resolved = RunCommandProcessor(
        packResolver: pinned == null
            ? _packResolver
            : _PinnedPackResolver(
                resolver,
                rest.first,
                pinned,
              ),
