      expect(await cmd().run(['1.2.3']), 0);
      expect(await cmd().run(['v1.2.3']), 0);
      expect(installs, [
        ['v1.2.3'],
        ['v1.2.3'],
      ]);
      expect(downloads.first.toString(),
